import{_ as d,o as e,c as o,ag as r}from"./chunks/framework.BaNuf0sO.js";const p=JSON.parse('{"title":"BadgeMark（徽标标记）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/display/docs/README-BadgeMark.md","filePath":"docs/core/src/components/display/docs/README-BadgeMark.md"}'),a={name:"docs/core/src/components/display/docs/README-BadgeMark.md"};function s(c,t,n,i,l,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="badgemark-徽标标记" tabindex="-1">BadgeMark（徽标标记） <a class="header-anchor" href="#badgemark-徽标标记" aria-label="Permalink to &quot;BadgeMark（徽标标记）&quot;">​</a></h1><blockquote><p>按 <code>badgeKey</code> 查 <code>bridge.badge</code> 注册表，命中且未过期则给默认插槽内容挂<strong>绝对定位角标</strong>（包 ElBadge，不挤压主体）；未命中渲染裸插槽、DOM 逐字节不变。 范式页：<code>apps/reference/src/pages/integration/badge/</code>（7 场景）；生产驱动点见 MenuTree / MenuItemSub / AppHeader / ActionBtn 内部接入。</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>何时用</strong>：自供 shell 自渲染导航、或业务自建的入口元素需要接徽标体系时</li><li><strong>何时不用</strong>：core 的菜单族与 <code>ActionBtn</code> <strong>已内置接入</strong>，用它们时 [MUST NOT] 再自行包一层</li><li><strong>opt-in 且零侵入</strong>：未 <code>app.use(bridge)</code> / key 未命中 / 标已过期 → 静默渲染裸插槽，[MUST NOT] 抛错</li><li>完整契约（标记类型 / <code>expireAt</code> 失效 / key 约定 / 已知限制 / 为何不做冒泡聚合）见 <a href="/done-coding-showcase/docs/core/src/bridge/docs/README.html">bridge 文档 · 徽标注册表</a></li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">BadgeMark</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> badgeKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/order/list&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;span&gt;订单列表&lt;/span&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">BadgeMark</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>app 侧往注册表写一条即出标：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bridge.badge.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/order/list&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { kind: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;new&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong><code>align</code> 怎么选：看被包内容盒是否紧贴文字</strong>（不是看宿主类型）。</li></ul><table tabindex="0"><thead><tr><th>宿主</th><th><code>.el-badge</code> 盒高</th><th>宿主高</th><th><code>corner</code> 落点</th><th>core 用</th></tr></thead><tbody><tr><td><code>ActionBtn</code></td><td>14px（紧贴文字行）</td><td>32px</td><td>角标顶齐按钮顶，上溢 <strong>0</strong></td><td><strong><code>corner</code></strong> 右上角</td></tr><tr><td><code>TabsHeader</code> tab</td><td>22px（紧贴）</td><td>40px</td><td>上溢 <strong>−1</strong>，不越界</td><td><strong><code>corner</code></strong> 右上角</td></tr><tr><td>菜单项 / AppHeader 模块条 / tile 卡片头</td><td><strong>50px（撑满整行）</strong></td><td>50px</td><td>钉在<strong>行顶</strong>、上溢 <strong>9px</strong> 侵入上一行</td><td><strong><code>middle</code></strong> 垂直居中</td></tr></tbody></table><p>差别根源：菜单项的 <code>span</code> 继承整行 <code>line-height</code>，<code>.el-badge</code> 盒跟着撑满一行，于是「内容顶边」≠「文字顶边」；按钮 / tab 的盒紧贴文字行，顶边即文字顶边。</p><ul><li><strong>[MUST NOT] 用 <code>top: N%</code> 或 ElBadge <code>offset</code> 魔数去凑</strong>：与字号 / 行高 / 主题 density 强耦合，一变就错位。盒紧贴文字的宿主用 <code>corner</code>，盒撑满行的用 <code>middle</code>。</li></ul><h3 id="硬约束-角标的出现-must-not-改变宿主尺寸" tabindex="-1">硬约束：角标的出现 [MUST NOT] 改变宿主尺寸 <a class="header-anchor" href="#硬约束-角标的出现-must-not-改变宿主尺寸" aria-label="Permalink to &quot;硬约束：角标的出现 [MUST NOT] 改变宿主尺寸&quot;">​</a></h3><p>两档均为<strong>绝对定位</strong>，不占布局位。实测证据：同一批按钮打标前后逐项宽度差 <strong>全 0</strong>。</p><p>代价是绝对定位不占位 → 角标必然向右<strong>逃逸出宿主边界</strong>，逃逸量 = <code>角标宽 − 13px</code>（EP 的 10px 内嵌已归零，另留 2px 让位；文字距按钮右缘 15px padding）：</p><table tabindex="0"><thead><tr><th>内置标</th><th>字数</th><th>宽</th><th>逃逸</th><th>后果</th></tr></thead><tbody><tr><td><strong>新</strong></td><td>1</td><td>26px</td><td>13px</td><td>基本不碰邻居</td></tr><tr><td><strong>更新 / 内测</strong></td><td>2</td><td>38px</td><td>25px</td><td>一般不碰邻居</td></tr><tr><td>开发中 / 规划中 / 待下线 / 未开通</td><td>3</td><td>50px</td><td>37px</td><td>右缘可能顶到水平相邻宿主</td></tr></tbody></table><p>⚠️ <strong>原「内置标文案 [MUST] ≤2 个汉字」那条约束已作废</strong>（甲方 2026-09-19 明示「不用关心太长」）。 逃逸量最终由消费方的布局间距决定，core [MUST NOT] 声称能保证零重叠；文案长度的后果由布局承担。 core <strong>自己的</strong>紧凑宿主照此办理：<code>AppHeader</code> 模块条各项首尾相接，挂标项按实测逃逸量补同宽右内边距（ii3dzw），本组件的绝对定位不变。 [MUST NOT] 因为这张表回推「所以该用图标 / 该截断」—— 见下文「内置档一律文字」。</p><p>⚠️ <strong>那条作废管的是「别拿宽度回推去换方案」，不是「文案可以随便改长」</strong>（v0.32.0，b9tmkc）： <strong>资讯三档回短是因为它们压根没被要求改过</strong>（撤回图标那批把悬浮气泡的 <code>label</code> 当正文搬了回来）， 逃逸量降回去只是<strong>顺带</strong>。状态四档三字<strong>照旧合法</strong>。</p><h3 id="尺寸-固定-12px-18px-不随-density-变" tabindex="-1">尺寸：固定 12px / 18px，不随 density 变 <a class="header-anchor" href="#尺寸-固定-12px-18px-不随-density-变" aria-label="Permalink to &quot;尺寸：固定 12px / 18px，不随 density 变&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th><th>来源</th></tr></thead><tbody><tr><td>字号</td><td><strong>12px</strong></td><td><code>--el-badge-font-size</code>（EP <strong>组件级</strong>变量，定义在 <code>.el-badge</code> 上，非 <code>:root</code>）</td></tr><tr><td>pill 高</td><td><strong>18px</strong></td><td><code>--el-badge-size</code></td></tr><tr><td>内 padding</td><td>0 6px</td><td><code>--el-badge-padding</code></td></tr></tbody></table><p>实测按钮 / tab / 菜单三处<strong>完全一致</strong>，文字在 pill 内垂直居中偏移均为 0（三处 <code>line-height</code> 虽不同——按钮 12px、tab 16.8px、菜单 56px 继承整行行高——但 pill 是 <code>inline-flex + align-items:center + 固定高</code>，不产生偏移）。</p><p>⚠️ <strong>不随主题 density 缩放</strong>：core 的 <code>THEME_FIELD_SPECS</code> 只往 <code>:root</code> 挂变量且未映射任何 badge 变量，故 density 档（compact / cozy / comfortable）不改角标尺寸。这是刻意的——角标应恒为全局最小号，跟着 density 缩放可能小到不可读。消费方要改自行覆盖 <code>--el-badge-font-size</code> / <code>--el-badge-size</code>。</p><h3 id="⚠️-换英文不能减宽-已实测-must-not-再试-本节留作依据备查" tabindex="-1">⚠️ 换英文<strong>不能</strong>减宽（已实测，[MUST NOT] 再试；本节留作依据备查） <a class="header-anchor" href="#⚠️-换英文不能减宽-已实测-must-not-再试-本节留作依据备查" aria-label="Permalink to &quot;⚠️ 换英文**不能**减宽（已实测，[MUST NOT] 再试；本节留作依据备查）&quot;">​</a></h3><p>12px 字号 + pill 内 padding 实测：</p><table tabindex="0"><thead><tr><th>中文</th><th>宽</th><th>英文</th><th>宽</th><th>差</th></tr></thead><tbody><tr><td>新</td><td>26</td><td>NEW</td><td>41</td><td><strong>+15</strong></td></tr><tr><td>更新</td><td>38</td><td>UPDATED</td><td>70</td><td><strong>+32</strong></td></tr><tr><td>内测</td><td>38</td><td>BETA</td><td>45</td><td><strong>+7</strong></td></tr><tr><td>开发中</td><td>50</td><td>WIP</td><td>36</td><td>−14</td></tr></tbody></table><p>汉字在小字号下表意密度远高于大写字母——除「开发中→WIP」外全部变宽。 ⚠️ 原结论「压宽度的正确手段是减字数」<strong>已不再适用</strong>（甲方明示不用关心太长）； 本节只保留一条仍然有效的结论：<strong>[MUST NOT] 为「更短」而把内置文案改成英文</strong>。</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>badgeKey</code></td><td><code>string?</code></td><td>无=不显</td><td>徽标键。菜单侧传路由 <code>path</code>，按钮侧传显式键</td></tr><tr><td><code>align</code></td><td><code>&quot;corner&quot; | &quot;middle&quot;</code></td><td><code>&quot;corner&quot;</code></td><td>角标垂直锚点：<code>corner</code>=骑内容顶边（按钮/图标）；<code>middle</code>=与内容垂直居中（纯文字标签）</td></tr></tbody></table><h3 id="emits-expose" tabindex="-1">Emits / Expose <a class="header-anchor" href="#emits-expose" aria-label="Permalink to &quot;Emits / Expose&quot;">​</a></h3><p>无。</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>#default</code></td><td>无</td><td>被挂标的内容；未命中时原样渲染，不加任何包裹层</td></tr></tbody></table><h2 id="内置标预设" tabindex="-1">内置标预设 <a class="header-anchor" href="#内置标预设" aria-label="Permalink to &quot;内置标预设&quot;">​</a></h2><p>文案与语义色由 core 统一定（跨 app 一致）；语义档解析到 <code>--el-color-*</code>，<strong>主题风格 / 亮暗切换自动跟随</strong>（规则 14，[MUST NOT] 写死色值）。</p><table tabindex="0"><thead><tr><th>kind</th><th>文案</th><th>语义色</th><th>为什么</th></tr></thead><tbody><tr><td><code>count</code></td><td><strong>数字</strong></td><td><code>danger</code> 红</td><td>待办数量要人行动，未读红点是全行业最强共识</td></tr><tr><td><code>new</code></td><td>新</td><td><code>success</code> 绿</td><td>正面资讯。[MUST NOT] 复用红——会与 <code>count</code> 撞色</td></tr><tr><td><code>updated</code></td><td>更新</td><td><code>primary</code> 主色</td><td>中性被动通知，不喧宾夺主</td></tr><tr><td><code>beta</code></td><td>内测</td><td><code>warning</code> 橙</td><td>能用但不稳定需谨慎</td></tr><tr><td><code>wip</code></td><td>开发中</td><td><code>info</code> 灰</td><td>尚不完善，中性、不引导点击。<strong>仅提示，不拦点击</strong></td></tr><tr><td><code>planned</code></td><td>规划中</td><td><code>info</code> 灰</td><td>还没开工，比 <code>wip</code> 更靠前。<strong>不进遮挡档</strong></td></tr><tr><td><code>deprecated</code></td><td>待下线</td><td><code>danger</code> 红</td><td>「要迁走」需要用户采取行动</td></tr><tr><td><code>locked</code></td><td>未开通</td><td><code>warning</code> 橙</td><td>权限边界，<strong>唯一拦点击的档</strong>；也是唯一<strong>拒绝隐藏</strong>的档</td></tr><tr><td><code>custom</code></td><td>自定义文案</td><td>缺省 <code>primary</code></td><td>内置档不够用时才用；<code>type</code> 只收语义档</td></tr><tr><td><code>anchor</code></td><td>——</td><td>——</td><td><strong>伪标 / 纯锚点</strong>：恒隐藏角标，只留 DOM 挂点供引导等消费方定位</td></tr></tbody></table><h3 id="🔴-内置档一律文字-must-not-再改图标" tabindex="-1">🔴 内置档<strong>一律文字</strong>，[MUST NOT] 再改图标 <a class="header-anchor" href="#🔴-内置档一律文字-must-not-再改图标" aria-label="Permalink to &quot;🔴 内置档**一律文字**，[MUST NOT] 再改图标&quot;">​</a></h3><p>甲方 2026-09-19（附菜单实拍图）：<strong>「badge 的图标撤掉，还是直接展示文字，两个字就是两个字、 三个字就是三个字（不用关心太长）」</strong>。图标态在真实菜单里是一排看不懂的小圈。</p><p><strong>原「≤2 汉字」的宽度约束随之作废</strong> —— 它当初的依据是「三字宽 50px、逃逸 36px 会压到水平 相邻宿主」，而甲方<strong>明确说不用关心太长</strong>。⇒ 实施方 [MUST NOT] 拿那条依据回推「所以还是该用 图标」，也 [MUST NOT] 自行折中（截断 / 省略号 / tooltip 代文字）—— 那是用没被授权的方案 绕过已下达的决定。逃逸的代价由消费方的布局间距承担，core 照旧不声称能保证零重叠。</p><p>⚠️ 这<strong>不是「把 v0.30 revert 掉」</strong>：状态四档（<code>wip</code> / <code>planned</code> / <code>deprecated</code> / <code>locked</code>） 在 ≤v0.29 时本来就是图标，本次是它们<strong>首次</strong>以文字出现。三档是新的一致态：</p><table tabindex="0"><thead><tr><th>版本</th><th>资讯三档 <code>new</code>/<code>updated</code>/<code>beta</code></th><th>状态四档 <code>wip</code>/<code>planned</code>/<code>deprecated</code>/<code>locked</code></th></tr></thead><tbody><tr><td>≤ v0.29</td><td>文字（新 / 更新 / 内测）</td><td>图标</td></tr><tr><td>v0.30</td><td>图标</td><td>图标</td></tr><tr><td>v0.31.0</td><td>文字，但<strong>文案被夹带改长</strong>（新上线 / 已更新 / 内测中）</td><td>文字</td></tr><tr><td><strong>v0.32.0</strong></td><td><strong>文字，文案回正（新 / 更新 / 内测）</strong></td><td>文字（不动）</td></tr></tbody></table><p>⚠️ <strong>形态本身在传达分类</strong>：资讯档短（1–2 字）、状态档三字 —— v0.31.0 那一版七档全三字，扫视时分不出两类。</p><p>图标是<strong>全族退场</strong>：<code>ElIcon</code> / <code>ElTooltip</code> / 预设的 <code>icon</code> 与 <code>iconScale</code> 字段一并删除。 悬浮气泡随之去掉 —— 它当初存在只为「语义随文字消失后补回来」，文字回来了它就是重复。</p><h2 id="展示开关-逐条-visible-全局默认" tabindex="-1">展示开关：逐条 <code>visible</code> + 全局默认 <a class="header-anchor" href="#展示开关-逐条-visible-全局默认" aria-label="Permalink to &quot;展示开关：逐条 `visible` + 全局默认&quot;">​</a></h2><p>徽标当初是拿来做新手引导的；有了 <code>forge-plugin-guide</code> 之后，<strong>徽标不再必须显示</strong>。</p><table tabindex="0"><thead><tr><th>层</th><th>写法</th><th>默认</th></tr></thead><tbody><tr><td>逐条</td><td><code>bridge.badge.set(key, { kind: &quot;new&quot;, visible: false })</code></td><td><code>undefined</code> = 跟随全局</td></tr><tr><td>全局</td><td><code>createCoreBridge({ badge: { defaultVisible: false } })</code> 或 <code>bridge.badge.setDefaultVisible(false)</code></td><td><strong><code>true</code>（展示）</strong></td></tr></tbody></table><p><strong>逐条显式值恒优先于全局默认</strong>（与本仓所有 config-hook 同口径）。 全局默认取 <code>true</code> 是为了不改变现有下游观感；把它关成不展示是消费方的选择。</p><h3 id="🔴-「配置了但不展示」与「没配置」是两回事" tabindex="-1">🔴 「配置了但不展示」与「没配置」是两回事 <a class="header-anchor" href="#🔴-「配置了但不展示」与「没配置」是两回事" aria-label="Permalink to &quot;🔴 「配置了但不展示」与「没配置」是两回事&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>注册表</th><th>DOM</th><th><code>data-dc-badge-key</code></th><th>引导能否定位</th></tr></thead><tbody><tr><td><strong>没配置</strong></td><td>无 entry</td><td>渲染<strong>裸插槽</strong>（无 <code>ElBadge</code>）</td><td>❌ 无</td><td>❌</td></tr><tr><td><strong>配置了但不展示</strong></td><td>有 entry</td><td>渲染 <code>ElBadge</code>，角标被藏</td><td>✅ 在</td><td>✅</td></tr></tbody></table><p>⇒ 隐藏 [MUST NOT] 用 <code>v-if</code> 掉整个 <code>ElBadge</code> —— 那会连挂点一起没掉， <code>forge-plugin-guide</code> 当场失去锚点。<strong>把徽标全部设为不展示时，引导仍能正常串出并定位。</strong></p><h3 id="藏法-0-尺寸-overflow-hidden-事件屏蔽-甲方裁定" tabindex="-1">藏法 = 0 尺寸 + <code>overflow:hidden</code> + 事件屏蔽（甲方裁定） <a class="header-anchor" href="#藏法-0-尺寸-overflow-hidden-事件屏蔽-甲方裁定" aria-label="Permalink to &quot;藏法 = 0 尺寸 + `overflow:hidden` + 事件屏蔽（甲方裁定）&quot;">​</a></h3><div class="language-less vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">less</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">width: 0; height: 0; </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">min-width</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 0; padding: 0; </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">border-width</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 0;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">overflow: hidden; </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pointer-events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: none;</span></span></code></pre></div><p>文字仍在 DOM 里但被裁掉，故 [MUST] 同时给 <code>aria-hidden=&quot;true&quot;</code>（0 尺寸只是<strong>视觉</strong>裁掉， 读屏照念）。</p><p>🔴 <strong>[MUST NOT] 用 <code>display: none</code>，也 [MUST NOT] 沿用 <code>ElBadge</code> 的 <code>hidden</code> prop</strong> （它内部就是把 sup 从布局里摘掉）。理由<strong>不是</strong>「保住锚点」—— 那是错的因果： <code>data-dc-badge-key</code> 挂在 <code>ElBadge</code> <strong>根元素</strong>（包着宿主内容的 wrapper，有真实尺寸）上， 不是那个十几 px 的 pill，两种藏法都不断锚。</p><p><strong>真正的理由是「仍然占位可测」</strong>：<code>display:none</code> 的元素 <code>getClientRects().length === 0</code>， 而这正是 <code>plugin-guide/src/anchor.ts</code> 的可见性判据（以及 <code>kq2m8w</code> 引导整页卡死 P0 的成因） 所依赖的那条线。保持「0 尺寸但仍在布局里」，可以让<strong>任何</strong>按 rect 判可见性的下游逻辑 不被隐藏态坑到。</p><h3 id="🔴-遮挡档-locked-拒绝隐藏" tabindex="-1">🔴 遮挡档（<code>locked</code>）<strong>拒绝隐藏</strong> <a class="header-anchor" href="#🔴-遮挡档-locked-拒绝隐藏" aria-label="Permalink to &quot;🔴 遮挡档（`locked`）**拒绝隐藏**&quot;">​</a></h3><p><code>BADGE_MASK_KINDS</code>（现仅 <code>locked</code>）<strong>不接受隐藏</strong>：逐条 <code>visible: false</code> 对它无效， 全局默认的「不展示」也不作用到它；dev 下会 <code>console.warn</code> 一句（静默忽略 = 消费方 以为设了其实没设）。</p><p>依据：<strong>遮挡是功能不是资讯</strong>。藏了会落进两种更坏的形态之一 —— 「隐藏了但仍然挡」⇒ 用户看到一个点不动又没有任何说明的按钮； 「隐藏了就不挡」⇒ 未开通的功能变成可点，功能性回退。</p><h3 id="anchor-只要挂点、不要角标" tabindex="-1"><code>anchor</code>：只要挂点、不要角标 <a class="header-anchor" href="#anchor-只要挂点、不要角标" aria-label="Permalink to &quot;`anchor`：只要挂点、不要角标&quot;">​</a></h3><p>想给某个菜单项 / 按钮做新手引导，但它本身没有「新 / 更新」之类的标要显示时用它。 [MUST NOT] 为此硬挂一个 <code>new</code> —— 那会在界面上多出一个用户看不懂的角标。</p><p><strong>与 <code>visible: false</code> 的关系（[MUST] 按此口径，[MUST NOT] 留两套说法）：两者都保留，语义不同。</strong></p><table tabindex="0"><thead><tr><th></th><th>语义</th><th>藏法</th></tr></thead><tbody><tr><td><code>kind: &quot;anchor&quot;</code></td><td>「这里<strong>本来就没有标</strong>」—— <code>kind</code> 无资讯语义 + 恒隐藏</td><td>同一套</td></tr><tr><td><code>visible: false</code></td><td>「<strong>有标</strong>（new / beta / …），只是此刻不显示」</td><td>同一套</td></tr></tbody></table><p>⇒ <code>anchor</code> <strong>不是</strong>新开关的语法糖：它已是发布契约，且语义是「无标」而非「有标先不显示」。 两者<strong>共用同一套藏法</strong>（0 尺寸 + <code>overflow:hidden</code> + 事件屏蔽）， [MUST NOT] 让它继续走 <code>ElBadge</code> 的 <code>hidden</code> —— 那就是「两种隐藏机制」。</p><h2 id="遮挡-只有-locked-一档拦点击" tabindex="-1">遮挡：只有 <code>locked</code> 一档拦点击 <a class="header-anchor" href="#遮挡-只有-locked-一档拦点击" aria-label="Permalink to &quot;遮挡：只有 `locked` 一档拦点击&quot;">​</a></h2><p>挂 <code>locked</code> 的宿主会被<strong>铺一层透明遮罩吃掉点击</strong>，同时打 <code>tabindex=&quot;-1&quot;</code> + <code>aria-disabled=&quot;true&quot;</code>（移出 Tab 序列，但读屏仍能读到该项并报告为不可用 —— 「未开通」是要让用户知道存在且可申请的功能，不是要藏起来）。</p><p><strong>其余全部 kind 照常可点</strong>，含 <code>wip</code>：<strong>开发中 ≠ 不可达</strong> —— 半成品页面让人点进去看是 正常预期，而未开通是<strong>权限边界</strong>，才必须拦。</p><p>点击被拦时走 <code>entry.onTrigger</code>；未配则出默认提示「请联系平台开通功能」。 ⚠️ <code>onTrigger</code> 只在<strong>拦得住</strong>时才有触发点 ⇒ 给 <code>wip</code> 配它不会被调用。 要拦某项就改挂 <code>locked</code>，[MUST NOT] 指望用 <code>onTrigger</code> 把可点档变成不可点。</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong><code>custom</code> 传色值字面量</strong>：<code>type</code> [MUST] 取语义档（<code>primary</code>/<code>success</code>/<code>warning</code>/<code>danger</code>/<code>info</code>），写死色跨主题不响应（规则 14）</li><li><strong>包纯文字却用默认 <code>corner</code></strong>：角标会悬在文字上方并溢出相邻行</li><li><strong>指望它做聚合</strong>：本组件只按 key 查表渲染，core [MUST NOT] 把子级的标上卷到父级；聚合由 app 自算后往父级 key 写 entry</li><li><strong>以为角标是实心底白字</strong>：<strong>已改镂空</strong>（见下节）。旧描述作废，[MUST NOT] 照旧假设</li><li><strong>以为内置档是图标 + 气泡</strong>：v0.30 那一版的形态，<strong>本版已全档改回文字</strong>，气泡随之去掉</li><li><strong>拿 <code>v-if</code> 藏徽标</strong>：会连 <code>data-dc-badge-key</code> 挂点一起没掉，引导插件当场定位不到；隐藏一律走 <code>visible</code></li><li><strong>给 <code>locked</code> 配 <code>visible: false</code></strong>：<strong>无效</strong>（遮挡是功能不是资讯），dev 下有 <code>console.warn</code></li></ul><h2 id="镂空-outline-观感" tabindex="-1">镂空（outline）观感 <a class="header-anchor" href="#镂空-outline-观感" aria-label="Permalink to &quot;镂空（outline）观感&quot;">​</a></h2><p>角标走<strong>镂空</strong>：浅底 + 语义色 1px 边框 + 语义色文字（原先是语义色实心底 + 白字）。</p><ul><li>落点在 <code>use-theme-apply</code> 的 <code>EP_STRUCTURAL_CSS</code>（与其余 EP 结构性修正同源）—— 角标由 <code>ElBadge</code> 渲染在它自己的 DOM 上，[MUST NOT] 在 <code>BadgeMark.vue</code> 写 scoped（打不中）。</li><li>颜色全走 <code>--el-color-&lt;档&gt;</code> / <code>--dc-core-*</code> 双源（规则 14），[MUST NOT] 写死。</li><li><strong>底不是纯透明</strong>：角标叠在宿主内容上，全透会透出下面的字 ⇒ 用 <code>--el-bg-color</code>（面色）打底。</li></ul><p>要退回实心：在消费方侧覆盖 <code>.el-badge__content</code>（<code>background-color</code> / <code>color</code> / <code>border</code>）。 [MUST NOT] 指望有 prop 开关 —— 观感是全局一致口径，不做成逐处可调。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>数据真源：<code>bridge.badge</code>（<code>bridge/badge.ts</code>）</li><li>内部 hook：<code>use-badge</code>（同级、不出桶；查表 + <code>expireAt</code> 判定 + 展示开关解析 + 全 app 共享 tick）</li><li>已接入的生产驱动点：<code>MenuTree</code> / <code>MenuItemSub</code> / <code>AppHeader</code> 模块条 / <code>ActionBtn</code></li></ul>',77)])])}const b=d(a,[["render",s]]);export{p as __pageData,b as default};
